<?php defined('BASEPATH') OR exit('No direct script access allowed');class Email_mailbox_model extends CI_Model{function __construct(){parent::__construct();$this->load->database();}function all($org){return array_map(array($this,'view'),$this->db->where('organization_id',$org)->order_by('created_at','DESC')->get('email_mailboxes')->result_array());}function one($id,$org){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('email_mailboxes')->row_array();return $r?$this->view($r):NULL;}function raw($id,$org){return $this->db->where(array('id'=>$id,'organization_id'=>$org))->get('email_mailboxes')->row_array();}function save($id,$org,$d){$now=date('Y-m-d H:i:s');$map=array('name'=>'name','emailAddress'=>'email_address','provider'=>'provider','imapHost'=>'imap_host','imapPort'=>'imap_port','smtpHost'=>'smtp_host','smtpPort'=>'smtp_port','username'=>'username');$set=array();foreach($map as $i=>$o)if(array_key_exists($i,$d))$set[$o]=$d[$i];if(array_key_exists('password',$d))$set['password_enc']=$d['password']===NULL?NULL:$this->encrypt($d['password']);if(!$id){$id=$this->uuid();$set+=array('id'=>$id,'organization_id'=>$org,'status'=>'pending','created_at'=>$now,'updated_at'=>$now);$this->db->insert('email_mailboxes',$set);}else{$set['updated_at']=$now;$this->db->where(array('id'=>$id,'organization_id'=>$org))->update('email_mailboxes',$set);if(!$this->one($id,$org))return NULL;}return $this->one($id,$org);}function remove($id,$org){$this->db->where(array('id'=>$id,'organization_id'=>$org))->delete('email_mailboxes');return $this->db->affected_rows()>0;}function test($id,$org){$r=$this->raw($id,$org);if(!$r)return NULL;$host=$r['smtp_host']?:$r['imap_host'];$port=$r['smtp_host']?$r['smtp_port']:$r['imap_port'];if(!$host||!$port){$ok=FALSE;$err='Mail server host and port are not configured';}else{$errno=0;$err='';$sock=@fsockopen($host,(int)$port,$errno,$err,5);$ok=(bool)$sock;if($sock)fclose($sock);if(!$ok)$err=$err?:'Connection failed';}$this->db->where('id',$id)->update('email_mailboxes',array('status'=>$ok?'configured':'error','error'=>$ok?NULL:substr($err,0,1000),'updated_at'=>date('Y-m-d H:i:s')));return array('ok'=>$ok,'status'=>$ok?'configured':'error','error'=>$ok?NULL:$err,'testedAt'=>date('c'));}function view($r){return array('id'=>$r['id'],'organizationId'=>$r['organization_id'],'name'=>$r['name'],'emailAddress'=>$r['email_address'],'provider'=>$r['provider'],'imapHost'=>$r['imap_host'],'imapPort'=>$r['imap_port']===NULL?NULL:(int)$r['imap_port'],'smtpHost'=>$r['smtp_host'],'smtpPort'=>$r['smtp_port']===NULL?NULL:(int)$r['smtp_port'],'username'=>$r['username'],'hasCredentials'=>!empty($r['password_enc']),'status'=>$r['status'],'lastSyncAt'=>$r['last_sync_at'],'error'=>$r['error'],'createdAt'=>$r['created_at'],'updatedAt'=>$r['updated_at']);}function password($id,$org){$r=$this->raw($id,$org);if(!$r||!$r['password_enc'])return NULL;$raw=base64_decode($r['password_enc'],TRUE);if($raw===FALSE||strlen($raw)<29)return NULL;$iv=substr($raw,0,12);$tag=substr($raw,12,16);$ct=substr($raw,28);$key=hash('sha256',(string)getenv('VP_ENCRYPTION_KEY'),TRUE);$out=openssl_decrypt($ct,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);return $out===FALSE?NULL:$out;}private function encrypt($s){$key=hash('sha256',(string)getenv('VP_ENCRYPTION_KEY'),TRUE);$iv=random_bytes(12);$tag='';$ct=openssl_encrypt($s,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);return base64_encode($iv.$tag.$ct);}private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
